-- Ingest Wrestling Observer Newsletter issue records from the official 2010 index PDF.
-- Generated from: /Users/jschairb-gwp/Downloads/Wrestling Observer Newsletter - 2010 - Index.pdf
-- Parsed issue rows: 1404
BEGIN;

UPDATE periodicals
   SET year_started = 1982,
       publisher = COALESCE(publisher, 'Dave Meltzer / Wrestling Observer Newsletter'),
       country = COALESCE(country, 'US'),
       language = COALESCE(language, 'English'),
       frequency = COALESCE(frequency, 'weekly'),
       type = COALESCE(type, 'newsletter'),
       source_url = COALESCE(source_url, '/Users/jschairb-gwp/Downloads/Wrestling Observer Newsletter - 2010 - Index.pdf'),
       confidence = 'high',
       notes = COALESCE(notes, 'Issue inventory sourced from The Official Index of The Wrestling Observer Newsletter, copyright 2010.')
 WHERE title = 'Wrestling Observer Newsletter' AND year_started = 1983;

VALUES ('Wrestling Observer Newsletter', 'Dave Meltzer / Wrestling Observer Newsletter', 'US', 'English', 1982, 'weekly', 'newsletter',
        'Issue inventory sourced from The Official Index of The Wrestling Observer Newsletter, copyright 2010.', 0, '/Users/jschairb-gwp/Downloads/Wrestling Observer Newsletter - 2010 - Index.pdf', 'high')
ON CONFLICT (title, year_started) DO UPDATE SET
    publisher = COALESCE(periodicals.publisher, EXCLUDED.publisher),
    country = COALESCE(periodicals.country, EXCLUDED.country),
    language = COALESCE(periodicals.language, EXCLUDED.language),
    frequency = COALESCE(periodicals.frequency, EXCLUDED.frequency),
    type = COALESCE(periodicals.type, EXCLUDED.type),
    source_url = COALESCE(periodicals.source_url, EXCLUDED.source_url),
    confidence = 'high';

WITH won AS (
    SELECT id FROM periodicals WHERE title = 'Wrestling Observer Newsletter' AND year_started = 1982
)
ON CONFLICT (periodical_id, publication_date) DO UPDATE SET
    issue_number = EXCLUDED.issue_number,
    source_url = EXCLUDED.source_url,
    confidence = EXCLUDED.confidence,
    notes = EXCLUDED.notes;

COMMIT;
